// Clearbit returns a list of possible companies. Keep a domain only if the name matches,
// then rate it: 'high' if the domain itself looks like the company name, otherwise 'review' (check by hand).
const c = $('Get companies to enrich').item.json;
let list = [];
try { list = JSON.parse($json.data || '[]'); } catch (e) { list = []; }

const base = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const clean = s => base(s)
  .replace(/\(.*\)/g, '')
  .replace(/\b(inc|llc|ltd|limited|gmbh|corp|corporation|co|plc|sa|ag|bv|group|holdings|technologies|technology|labs|hq|the|an|a)\b/g, '')
  .replace(/[^a-z0-9]/g, '');
const SUFFIX = /(hq|app|ai|io|grp|group|inc|global|team|labs|software|tech)$/;
const want = clean(c.company_name);

let pick = null;
for (const s of list) {
  const got = clean(s.name);
  if (got && got === want) { pick = s; break; }
  if (!pick && got && want && (got.startsWith(want) || want.startsWith(got))) pick = s;
}

const domain = pick ? String(pick.domain).toLowerCase().replace(/^www\./, '') : null;
let domain_confidence = null;
if (domain) {
  const d = domain.split('.')[0].replace(/[^a-z0-9]/g, '');
  const dc = d.replace(/^(go|get|try|use|join|hey|my)/, '').replace(SUFFIX, '');
  const nc = want.replace(SUFFIX, '');
  domain_confidence = (d === want || dc === nc || d === nc || dc === want) ? 'high' : 'review';
}

return { json: {
  company_key: c.company_key,
  company_name: c.company_name,
  company_slug: c.company_slug,
  domain,
  domain_confidence,
  employee_range: null,
  employee_count: null,
  hq: null,
  enriched_at: new Date().toISOString(),
  enrich_error: domain ? null : (list.length ? `No confident name match (top result: ${list[0].name} / ${list[0].domain})` : 'No Clearbit result')
}};
